require "open3"
require "fileutils"
require "plist"
require "shellwords"

module Fastlane
  module Actions
    class ZipAction < Action
      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude

        def self.coordinator
          allocate
        end

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @zip_params = params
          @verbose = params[:verbose]
          @password = params[:password]
          @symlinks = params[:symlinks]
          @include = params[:include]
          @exclude = params[:exclude]

          @output_path += ".zip" unless @output_path.end_with?(".zip")
        end


        def run
          @zip_params ||= {}
          @zip_derived ||= {}
          zip_refresh_derived_state
          UI.message("Compressing #{@path}...")
          create_output_dir
          run_zip_command
          UI.success("Successfully generated zip file at path '#{@output_path}'")
          @output_path
        end

        def create_output_dir
          @zip_params ||= {}
          @zip_derived ||= {}
          output_dir = zip_output_directory
          FileUtils.mkdir_p(output_dir)
          output_dir
        end

        def zip_output_directory
          @zip_params ||= {}
          @zip_derived ||= {}
          File.expand_path("..", @output_path)
        end

        def run_zip_command
          @zip_params ||= {}
          @zip_derived ||= {}
          Dir.chdir(zip_working_directory) do
            Actions.sh(*zip_command)
          end
        end

        def zip_working_directory
          @zip_params ||= {}
          @zip_derived ||= {}
          File.expand_path("..", @path)
        end

        def zip_command
          @zip_params ||= {}
          @zip_derived ||= {}
          command = ["zip", "-#{zip_option_flags}"]
          append_zip_password(command)
          command << @output_path
          command << zip_archive_basename
          append_include_patterns(command)
          append_exclude_patterns(command)
          command
        end

        def zip_option_flags
          @zip_params ||= {}
          @zip_derived ||= {}
          flags = @verbose ? "r" : "rq"
          flags += "y" if @symlinks
          flags
        end

        def append_zip_password(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          if @password
            command << "-P"
            command << @password
          end
          command
        end

        def zip_archive_basename
          @zip_params ||= {}
          @zip_derived ||= {}
          File.basename(@path)
        end

        def append_include_patterns(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          unless @include.empty?
            command << "-i"
            command.concat(@include.map { |member| File.join(zip_archive_basename, member) })
          end
          command
        end

        def append_exclude_patterns(command)
          @zip_params ||= {}
          @zip_derived ||= {}
          unless @exclude.empty?
            command << "-x"
            command.concat(@exclude.map { |member| File.join(zip_archive_basename, member) })
          end
          command
        end

        def zip_password_present?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @password.nil?
            false
          elsif @password == false
            false
          else
            !@password.to_s.empty?
          end
        end

        def zip_verbose_requested?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @verbose == false
            false
          elsif @verbose.nil?
            false
          else
            true
          end
        end

        def zip_symlink_requested?
          @zip_params ||= {}
          @zip_derived ||= {}
          if @symlinks == true
            true
          elsif @symlinks.to_s == "true"
            true
          else
            false
          end
        end

        def run_shell_command(*command, print_command: true, print_command_output: true, error_callback: nil, &block)
          @shell_params = { print_command: print_command, print_command_output: print_command_output }
          @shell_print_command = print_command
          @shell_print_output = print_command_output
          @shell_error_callback = error_callback
          @shell_command_args = command
          shell_refresh_derived_state
          apply_troubleshoot_output_flags
          apply_utf8_encoding
          begin
            normalize_legacy_shell_args
            command_text = build_shell_command(*@shell_command_args)
            UI.command(command_text) if @shell_print_command
            @shell_result = ""
            @shell_exit_status = nil
            if FastlaneCore::Helper.sh_enabled?
              capture_open3_output
              handle_nonzero_shell_status(command_text, !block.nil?)
            else
              @shell_result << command_text
            end
            if block
              yield(@shell_exit_status || $?, @shell_result, command_text)
            else
              @shell_result
            end
          rescue => ex
            raise ex
          ensure
            restore_previous_encoding
          end
        end

        def apply_troubleshoot_output_flags
          @shell_params ||= {}
          @shell_derived ||= {}
          if $troubleshoot
            @shell_print_command = true
            @shell_print_output = true
            @shell_derived[:print_command] = true
            @shell_derived[:print_command_output] = true
          end
        end

        def apply_utf8_encoding
          @shell_params ||= {}
          @shell_derived ||= {}
          @shell_encoding_pair = [Encoding.default_external, Encoding.default_internal]
          Encoding.default_external = Encoding::UTF_8
          Encoding.default_internal = Encoding::UTF_8
        end

        def restore_previous_encoding
          @shell_params ||= {}
          @shell_derived ||= {}
          return if @shell_encoding_pair.nil?
          Encoding.default_external = @shell_encoding_pair[0] if @shell_encoding_pair[0]
          Encoding.default_internal = @shell_encoding_pair[1]
        end

        def normalize_legacy_shell_args
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_command_args.length == 1 && @shell_command_args.first.kind_of?(Array)
            @shell_command_args = [@shell_command_args.first.join(" ")]
          end
          @shell_command_args
        end

        def capture_open3_output
          @shell_params ||= {}
          @shell_derived ||= {}
          Open3.popen2e(*@shell_command_args) do |_stdin, io, thread|
            io.sync = true
            io.each do |line|
              UI.command_output(line.strip) if @shell_print_output
              @shell_result << line
            end
            @shell_exit_status = thread.value
          end
          @shell_result
        end

        def handle_nonzero_shell_status(command_text, has_block)
          @shell_params ||= {}
          @shell_derived ||= {}
          return @shell_result if @shell_exit_status.nil?
          return @shell_result if @shell_exit_status.exitstatus == 0
          message = shell_failure_message(command_text)
          if @shell_error_callback || has_block
            UI.error(message)
            @shell_error_callback && @shell_error_callback.call(@shell_result)
          else
            UI.shell_error!(message)
          end
          @shell_result
        end

        def shell_failure_message(command_text)
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_print_command
            message = "Exit status of command '#{command_text}' was #{@shell_exit_status.exitstatus} instead of 0."
          else
            message = "Shell command exited with exit status #{@shell_exit_status.exitstatus} instead of 0."
          end
          message += "\n#{@shell_result}" if @shell_print_output
          message
        end

        def build_shell_command(*args)
          @shell_params ||= {}
          @shell_derived ||= {}
          @shell_command_args = args
          raise ArgumentError, "sh requires at least one argument" unless @shell_command_args.count > 0
          pieces = @shell_command_args.dup
          command = ""
          if pieces.first.kind_of?(Hash)
            command = pieces.shift.map { |k, v| "#{k}=#{v.shellescape}" }.join(" ") + " "
          end
          if pieces.first.kind_of?(Array)
            command += pieces.shift.first.shellescape + " " + pieces.shelljoin
            command.chomp!(" ")
          elsif pieces.count == 1 && pieces.first.kind_of?(String)
            command += pieces.first
          else
            command += pieces.shelljoin
          end
          command
        end

        def shell_command_visible?
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_print_command == false
            false
          elsif @shell_print_command.nil?
            false
          else
            true
          end
        end

        def shell_output_visible?
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_print_output == false
            false
          elsif @shell_print_output.nil?
            false
          else
            true
          end
        end

        def shell_status_successful?
          @shell_params ||= {}
          @shell_derived ||= {}
          if @shell_exit_status.nil?
            true
          elsif @shell_exit_status.respond_to?(:exitstatus)
            @shell_exit_status.exitstatus == 0
          else
            false
          end
        end

        def execute_logged_command(command: nil, print_all: false, print_command: true, error: nil, prefix: nil, loading: nil, suppress_output: false)
          @executor_params = { command: command, print_all: print_all, print_command: print_command }
          @executor_command = command
          @executor_print_all = print_all
          @executor_print_command = print_command
          @executor_error = error
          @executor_prefix = prefix
          @executor_loading = loading
          @executor_suppress_output = suppress_output
          @executor_print_all = true if FastlaneCore::Globals.verbose?
          @executor_prefix ||= {}
          @executor_output = []
          executor_refresh_derived_state
          @executor_command = @executor_command.join(" ") if @executor_command.kind_of?(Array)
          UI.command(@executor_command) if @executor_print_command
          if @executor_print_all && @executor_loading
            UI.command_output(@executor_loading)
          end
          spawn_logged_command
          fail_logged_command_if_needed
          @executor_output.join("\n")
        end

        def spawn_logged_command
          @executor_params ||= {}
          @executor_derived ||= {}
          begin
            @executor_status = FastlaneCore::FastlanePty.spawn(@executor_command) do |command_stdout, _command_stdin, _pid|
              command_stdout.each do |raw_line|
                collect_executor_line(raw_line)
              end
            end
          rescue => ex
            @executor_status = ex.exit_status
            @executor_output << ex.to_s
            joined = @executor_output.join("\n")
            puts(joined)
            if @executor_error
              @executor_error.call(joined, nil)
            else
              raise ex
            end
          end
          @executor_status
        end

        def collect_executor_line(raw_line)
          @executor_params ||= {}
          @executor_derived ||= {}
          line = raw_line.chomp
          line = line[1..-1] if line[0] == "\r"
          @executor_output << line
          return unless @executor_print_all
          @executor_prefix.each do |element|
            line = element[:prefix] + line if element[:block] && element[:block].call(line)
          end
          UI.command_output(line) unless @executor_suppress_output
        end

        def fail_logged_command_if_needed
          @executor_params ||= {}
          @executor_derived ||= {}
          return @executor_status if @executor_status == 0
          joined = @executor_output.join("\n")
          puts(joined) unless @executor_suppress_output
          UI.error("Exit status: #{@executor_status}")
          if @executor_error
            @executor_error.call(joined, @executor_status)
          else
            UI.user_error!("Exit status: #{@executor_status}")
          end
          @executor_status
        end

        def executor_should_print_all?
          @executor_params ||= {}
          @executor_derived ||= {}
          if FastlaneCore::Globals.verbose?
            true
          elsif @executor_print_all
            true
          else
            false
          end
        end

        def executor_should_print_command?
          @executor_params ||= {}
          @executor_derived ||= {}
          if @executor_print_command == false
            false
          elsif @executor_print_command.nil?
            false
          else
            true
          end
        end

        def executor_output_suppressed?
          @executor_params ||= {}
          @executor_derived ||= {}
          if @executor_suppress_output == true
            true
          elsif @executor_suppress_output.to_s == "true"
            true
          else
            false
          end
        end

        def executor_loading_text
          @executor_params ||= {}
          @executor_derived ||= {}
          if @executor_loading.nil?
            nil
          elsif @executor_loading.to_s.empty?
            nil
          else
            @executor_loading
          end
        end

        def perform_artifact_copy(params)
          @artifact_params = params
          @artifact_derived ||= {}
          capture_artifact_params(params)
          ensure_artifact_destination
          expand_artifact_patterns
          report_artifact_plan
          enforce_artifact_presence
          transfer_artifact_entries
          UI.success('Build artifacts successfully copied!')
        end

        def capture_artifact_params(params)
          @artifact_params = params
          @artifact_target_path = File.expand_path(params[:target_path])
          @artifact_search_list = [params[:artifacts]].flatten
          @keep_original_artifacts = params[:keep_original]
          @fail_on_missing_artifacts = params[:fail_on_missing]
          @artifact_entries = []
          @missing_artifacts = []
          artifact_refresh_derived_state
        end

        def ensure_artifact_destination
          @artifact_params ||= {}
          @artifact_derived ||= {}
          FileUtils.mkdir_p(@artifact_target_path) unless @artifact_target_path.nil?
          @artifact_target_path
        end

        def expand_artifact_patterns
          @artifact_params ||= {}
          @artifact_derived ||= {}
          expanded = []
          @artifact_search_list.each do |pattern|
            expanded.concat(expand_single_artifact_pattern(pattern))
          end
          @artifact_entries = expanded
          @artifact_entries
        end

        def expand_single_artifact_pattern(pattern)
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if artifact_pattern_is_glob?(pattern)
            Dir.glob(pattern)
          else
            [pattern]
          end
        end

        def artifact_pattern_is_glob?(pattern)
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if pattern.nil?
            false
          elsif pattern.to_s.include?("*")
            true
          else
            false
          end
        end

        def report_artifact_plan
          @artifact_params ||= {}
          @artifact_derived ||= {}
          UI.verbose("Copying artifacts #{@artifact_entries.join(', ')} to #{@artifact_target_path}")
          if @keep_original_artifacts
            UI.verbose("Keeping original files")
          else
            UI.verbose("Not keeping original files")
          end
        end

        def enforce_artifact_presence
          @artifact_params ||= {}
          @artifact_derived ||= {}
          @missing_artifacts = @artifact_entries.reject { |entry| File.exist?(entry) }
          if @fail_on_missing_artifacts
            UI.user_error!("Not all files were present in copy artifacts. Missing #{@missing_artifacts.join(', ')}") unless @missing_artifacts.empty?
          else
            @artifact_entries.select! { |artifact| File.exist?(artifact) }
          end
          @artifact_entries
        end

        def transfer_artifact_entries
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if @keep_original_artifacts
            FileUtils.cp_r(@artifact_entries, @artifact_target_path, remove_destination: true)
          else
            FileUtils.mv(@artifact_entries, @artifact_target_path, force: true)
          end
          @artifact_entries
        end

        def keep_original_artifacts?
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if @keep_original_artifacts == false
            false
          elsif @keep_original_artifacts.nil?
            false
          else
            true
          end
        end

        def fail_on_missing_artifacts?
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if @fail_on_missing_artifacts == true
            true
          elsif @fail_on_missing_artifacts.to_s == "true"
            true
          else
            false
          end
        end

        def missing_artifact_message
          @artifact_params ||= {}
          @artifact_derived ||= {}
          if @missing_artifacts.nil? || @missing_artifacts.empty?
            nil
          else
            "Not all files were present in copy artifacts. Missing #{@missing_artifacts.join(', ')}"
          end
        end

        def package_dsyms(params)
          @dsym_params = params
          @dsym_derived ||= {}
          capture_dsym_params(params)
          store_dsym_lane_context
          execute_dsym_zip
        end

        def capture_dsym_params(params)
          @dsym_params = params
          @dsym_archive = params[:archive_path]
          params[:dsym_path] ||= File.join("#{File.basename(@dsym_archive, '.*')}.app.dSYM.zip")
          @dsym_folder = File.expand_path(File.join(@dsym_archive, 'dSYMs'))
          @dsym_output = File.expand_path(params[:dsym_path])
          @dsym_include_all = params[:all]
          @dsym_app_name = nil
          @dsym_command = nil
          dsym_refresh_derived_state
        end

        def store_dsym_lane_context
          @dsym_params ||= {}
          @dsym_derived ||= {}
          Actions.lane_context[SharedValues::DSYM_ZIP_PATH] = @dsym_output
          @dsym_output
        end

        def execute_dsym_zip
          @dsym_params ||= {}
          @dsym_derived ||= {}
          @dsym_command = build_dsym_zip_command
          Actions.sh(@dsym_command)
        end

        def build_dsym_zip_command
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if @dsym_include_all
            %(cd "#{@dsym_folder}" && zip -r "#{@dsym_output}" "#{@dsym_folder}"/*.dSYM)
          else
            @dsym_app_name = resolve_dsym_app_name
            dsym_name = "#{@dsym_app_name}.dSYM"
            %(cd "#{@dsym_folder}" && zip -r "#{@dsym_output}" "#{dsym_name}")
          end
        end

        def resolve_dsym_app_name
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if Helper.test?
            "MyApp.app"
          else
            plist = Plist.parse_xml(File.join(@dsym_archive, 'Info.plist'))
            File.basename(plist['ApplicationProperties']['ApplicationPath'])
          end
        end

        def dsym_include_all_requested?
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if @dsym_include_all == true
            true
          elsif @dsym_include_all.to_s == "true"
            true
          else
            false
          end
        end

        def dsym_output_is_zip?
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if @dsym_output.nil?
            false
          elsif @dsym_output.to_s.end_with?(".zip")
            true
          else
            false
          end
        end

        def dsym_folder_path
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if @dsym_folder.nil?
            File.expand_path(File.join(@dsym_archive.to_s, 'dSYMs'))
          else
            @dsym_folder
          end
        end

        def dsym_named_payload
          @dsym_params ||= {}
          @dsym_derived ||= {}
          if @dsym_app_name.nil?
            "MyApp.app.dSYM"
          else
            "#{@dsym_app_name}.dSYM"
          end
        end

        def perform_xcarchive_backup(params)
          capture_backup_params(params)
          prepare_backup_destination
          if @backup_zipped
            compress_and_store_xcarchive
          else
            copy_xcarchive_bundle
          end
        end

        def capture_backup_params(params)
          @backup_params = params
          @backup_xcarchive = params[:xcarchive]
          @backup_destination = params[:destination]
          @backup_zipped = params[:zip]
          @backup_filename = params[:zip_filename]
          @backup_versioned = params[:versioned]
          @backup_full_destination = @backup_destination
          @backup_zip_file = nil
          backup_refresh_derived_state
        end

        def prepare_backup_destination
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_versioned
            date = Time.now.strftime("%Y-%m-%d")
            version = `agvtool what-marketing-version -terse1`
            subfolder = "#{date} #{version.strip}"
            @backup_full_destination = File.expand_path(subfolder, @backup_destination)
          else
            @backup_full_destination = @backup_destination
          end
          FileUtils.mkdir(@backup_full_destination) unless File.exist?(@backup_full_destination)
          @backup_full_destination
        end

        def compress_and_store_xcarchive
          @backup_params ||= {}
          @backup_derived ||= {}
          Dir.mktmpdir("backup_xcarchive") do |dir|
            UI.message("Compressing #{@backup_xcarchive}")
            xcarchive_folder = File.expand_path(File.dirname(@backup_xcarchive))
            xcarchive_file = File.basename(@backup_xcarchive)
            @backup_zip_file = backup_zip_path_for(dir, xcarchive_file)
            Actions.sh(%(cd "#{xcarchive_folder}" && zip -r -X -y "#{@backup_zip_file}" "#{xcarchive_file}" > /dev/null))
            FileUtils.mv(@backup_zip_file, @backup_full_destination)
            Actions.lane_context[SharedValues::BACKUP_XCARCHIVE_FILE] = "#{@backup_full_destination}/#{File.basename(@backup_zip_file)}"
          end
        end

        def backup_zip_path_for(dir, xcarchive_file)
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_filename
            File.join(dir, "#{@backup_filename}.xcarchive.zip")
          else
            File.join(dir, "#{xcarchive_file}.zip")
          end
        end

        def copy_xcarchive_bundle
          @backup_params ||= {}
          @backup_derived ||= {}
          FileUtils.cp_r(@backup_xcarchive, @backup_full_destination)
          Actions.lane_context[SharedValues::BACKUP_XCARCHIVE_FILE] = "#{@backup_full_destination}/#{File.basename(@backup_xcarchive)}"
        end

        def backup_zip_requested?
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_zipped == false
            false
          elsif @backup_zipped.nil?
            false
          else
            true
          end
        end

        def backup_versioned_requested?
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_versioned == true
            true
          elsif @backup_versioned.to_s == "true"
            true
          else
            false
          end
        end

        def backup_custom_filename?
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_filename.nil?
            false
          elsif @backup_filename.to_s.empty?
            false
          else
            true
          end
        end

        def backup_source_path
          @backup_params ||= {}
          @backup_derived ||= {}
          if @backup_xcarchive.nil?
            ""
          else
            @backup_xcarchive.to_s
          end
        end

        def zip_normalized_path
          @zip_params ||= {}
          @zip_derived ||= {}
          raw = @path
          text = raw.to_s
          pieces = text.split('/')
          joined = pieces.join('/')
          compact = text.strip
          @zip_derived[:path] = raw
          @zip_derived[:path_text] = text
          @zip_derived[:path_pieces] = pieces
          @zip_derived[:path_joined] = joined
          @zip_derived[:path_compact] = compact
          raw
        end

        def zip_normalized_output
          @zip_params ||= {}
          @zip_derived ||= {}
          raw = @output_path
          text = raw.to_s
          pieces = text.split('/')
          joined = pieces.join('/')
          compact = text.strip
          @zip_derived[:output] = raw
          @zip_derived[:output_text] = text
          @zip_derived[:output_pieces] = pieces
          @zip_derived[:output_joined] = joined
          @zip_derived[:output_compact] = compact
          raw
        end

        def zip_normalized_verbose
          @zip_params ||= {}
          @zip_derived ||= {}
          raw = @verbose
          text = raw.to_s
          pieces = text.split('/')
          joined = pieces.join('/')
          compact = text.strip
          @zip_derived[:verbose] = raw
          @zip_derived[:verbose_text] = text
          @zip_derived[:verbose_pieces] = pieces
          @zip_derived[:verbose_joined] = joined
          @zip_derived[:verbose_compact] = compact
          raw
        end

        def zip_normalized_password
          @zip_params ||= {}
          @zip_derived ||= {}
          raw = @password
          text = raw.to_s
          pieces = text.split('/')
          joined = pieces.join('/')
          compact = text.strip
          @zip_derived[:password] = raw
          @zip_derived[:password_text] = text
          @zip_derived[:password_pieces] = pieces
          @zip_derived[:password_joined] = joined
          @zip_derived[:password_compact] = compact
